// Assimilation: the slime spreads through the player with every story hour.
// This runs after the AI, so the turn's slime contact and remedies are already in self.value.
const traits = owner.traits;
const panic = owner.stats.Panic;

// 1. The base rate: two points for each story hour.
let pointsPerHour = 2;

// 2. The change feeds itself. Once the skin turns translucent at 40, the slime has a hold and spreads faster.
// It reads the value from the start of the turn, so one big splash of slime does not also speed up this turn.
if (self.previous.value >= 40) pointsPerHour += 1;

// 3. A racing heart pumps it through faster. Panic is read as a share of its max,
// because Morbid Curiosity raises that max and half of it should still mean "half panicked".
if (panic.value / panic.max >= 0.5) pointsPerHour += 1;

// 4. What slows it: a nurse's careful habits, and the effort of Fight It.
if (traits["Night-Shift Nurse"].enabled) pointsPerHour -= 1;
if (traits["Fight It"].enabled) pointsPerHour -= 2;

// 5. Spread for the hours this turn took. Holding on can stop the spread, but only remedies push it back,
// so the rate never goes below zero.
self.value += Math.max(0, pointsPerHour) * clock.deltaHours;
